import tailwindcss from '@tailwindcss/vite';
import { sveltekit } from '@sveltejs/kit/vite';
import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { marked } from 'marked';
import { defineConfig, type Plugin } from 'vite';

const CHANGELOG_ID = 'virtual:changelog';
const CHANGELOG_PATH = resolve('CHANGELOG.md');

// Serves CHANGELOG.md (generated by `bun run changelog`) as prerendered HTML, so
// the markdown parser never ships to the client. Empty when the file is missing.
function changelog(): Plugin {
	return {
		name: 'changelog',
		resolveId(id) {
			if (id === CHANGELOG_ID) return '\0' + CHANGELOG_ID;
		},
		load(id) {
			if (id !== '\0' + CHANGELOG_ID) return;
			this.addWatchFile(CHANGELOG_PATH);
			const markdown = existsSync(CHANGELOG_PATH) ? readFileSync(CHANGELOG_PATH, 'utf8') : '';
			return `export default ${JSON.stringify(marked.parse(markdown, { async: false }))};`;
		}
	};
}

export default defineConfig({
	esbuild: {
		drop: process.argv.includes('dev') ? [] : ['console']
	},
	server: {},
	plugins: [changelog(), tailwindcss(), sveltekit()]
});
